/* Disk-backed temporary files shared by the offscreen page and its MP4 worker. */
(() => {
    const ROOT = 'drive-preview-exporter-temp';

    async function root() {
        if (!navigator.storage?.getDirectory) {
            throw new Error('Disk-backed storage (OPFS) is unavailable in this browser.');
        }
        return (await navigator.storage.getDirectory()).getDirectoryHandle(ROOT, { create: true });
    }

    // Job identifiers are generated by the extension, never supplied by websites.
    function folderName(jobId) {
        return String(jobId).replace(/[^a-zA-Z0-9_-]/g, '_');
    }

    async function folder(jobId) {
        return (await root()).getDirectoryHandle(folderName(jobId), { create: true });
    }

    async function prepare(jobId) {
        const base = await root();
        // Delete temporary downloads left by a browser crash after three days.
        for await (const [name, handle] of base.entries()) {
            if (name === folderName(jobId) || handle.kind !== 'directory') continue;
            try {
                const marker = await handle.getFileHandle('created.txt');
                const created = Number(await (await marker.getFile()).text());
                if (created && Date.now() - created > 3 * 86400000) {
                    await base.removeEntry(name, { recursive: true });
                }
            } catch (_) { /* Never delete unknown or active directories. */ }
        }
        try { await base.removeEntry(folderName(jobId), { recursive: true }); }
        catch (error) { if (error.name !== 'NotFoundError') throw error; }
        const jobDirectory = await base.getDirectoryHandle(folderName(jobId), { create: true });
        const marker = await jobDirectory.getFileHandle('created.txt', { create: true });
        const writer = await marker.createWritable();
        await writer.write(String(Date.now()));
        await writer.close();
    }

    async function createStream(jobId, label) {
        const handle = await (await folder(jobId)).getFileHandle(`${label}.part`, { create: true });
        const writer = await handle.createWritable({ keepExistingData: false });
        let closed = false;
        return {
            // One writable stream serializes concurrent workers' positioned writes.
            async write(position, bytes) {
                if (closed) throw new Error('The temporary file is closed.');
                await writer.write({ type: 'write', position, data: bytes });
            },
            async reset() {
                if (closed) throw new Error('The temporary file is closed.');
                await writer.truncate(0);
            },
            async finish() {
                if (!closed) { closed = true; await writer.close(); }
                return handle.getFile(); // File is disk-backed; no full-file array allocation.
            },
            async abort() {
                if (closed) return;
                closed = true;
                try { await writer.abort(); } catch (_) {}
            }
        };
    }

    async function outputFile(jobId) {
        const handle = await (await folder(jobId)).getFileHandle('output.mp4');
        return handle.getFile();
    }

    async function remove(jobId) {
        try { await (await root()).removeEntry(folderName(jobId), { recursive: true }); }
        catch (error) { if (error.name !== 'NotFoundError') throw error; }
    }

    window.GDriveVideoDiskStorage = { prepare, createStream, outputFile, remove };
})();
